const m = Math.floor(seconds / 60).toString().padStart(2, '0');
const s = (seconds % 60).toString().padStart(2, '0');
document.getElementById('moca-timer').textContent = `${m}:${s}`;
}, 1000);
}
}

function resetTimer() {
clearInterval(timerInterval);
timerInterval = null;
seconds = 0;
document.getElementById('moca-timer').textContent = "00:00";
