function renderizarItens() {
const container = document.getElementById("mocaForm");
container.innerHTML = "";

mocaData.forEach((item) => {
const div = document.createElement("div");
div.className = item.type === "checkbox_group" || item.type === "info" ? "item-card col-span-full" : "item-card";
div.id = `card_${item.id}`;

let htmlContent = `
<div class="mb-4">
<h3 class="text-[15px] font-bold text-navy leading-snug border-b-2 border-slate-100 pb-2 mb-2">${item.category}</h3>
<p class="text-[12px] text-slate-600 font-medium">${item.explain}</p>
</div>
`;

if (item.type === "radio") {
let opts = `<option value="" disabled selected>अंक चुनें...</option>`;
item.options.forEach(op => { opts += `<option value="${op.val}">${op.text}</option>`; });
htmlContent += `<select id="${item.id}" class="item-select" data-type="radio" data-max="${item.max}">${opts}</select>`;
} else if (item.type === "checkbox_group") {
htmlContent += `<div class="moca-checkbox-group" data-group="${item.id}" data-max="${item.max}">`;
item.items.forEach(cb => {
htmlContent += `
<label class="custom-option-label" id="lbl_${cb.id}">
<input type="checkbox" id="${cb.id}" class="custom-option-input" value="${cb.val}" data-zero="${cb.isZero ? 'true' : 'false'}" onchange="handleCheckboxChange('${item.id}', '${cb.id}')">
<span>${cb.label}</span>
</label>
`;
});
htmlContent += `</div>`;
}

if (item.image) {
htmlContent += `<img src="${item.image}" alt="${item.category}" class="moca-image" loading="lazy" width="${item.imgWidth}" height="${item.imgHeight}">`;
}

div.innerHTML = htmlContent;
container.appendChild(div);

if (item.type === "radio") {
document.getElementById(item.id).addEventListener("change", () => {
document.getElementById(`card_${item.id}`).classList.remove("error");
atualizarBarraGlobal();
});
}
});
}

// Lida com exclusividade dos checkboxes (se marcar "zero", desmarca as outras)
window.handleCheckboxChange = function(groupId, cbId) {
const cb = document.getElementById(cbId);
const isZero = cb.getAttribute("data-zero") === "true";
const groupDiv = document.querySelector(`[data-group="${groupId}"]`);
const allCbs = groupDiv.querySelectorAll('.custom-option-input');

if (isZero && cb.checked) {
allCbs.forEach(other => {
if (other.id !== cbId) { other.checked = false; document.getElementById(`lbl_${other.id}`).classList.remove('checked'); }
});
} else if (!isZero && cb.checked) {
allCbs.forEach(other => {
if (other.getAttribute("data-zero") === "true") { other.checked = false; document.getElementById(`lbl_${other.id}`).classList.remove('checked'); }
});
}

allCbs.forEach(c => {
if (c.checked) document.getElementById(`lbl_${c.id}`).classList.add('checked');
else document.getElementById(`lbl_${c.id}`).classList.remove('checked');
});

document.getElementById(`card_${groupId}`).classList.remove("error");
atualizarBarraGlobal();
};

function atualizarBarraGlobal() {
let preenchidos = 0;
mocaData.forEach((i) => {
if (i.type === "info") return;
if (i.type === "radio") {
if (document.getElementById(i.id).value !== "") preenchidos++;
} else if (i.type === "checkbox_group") {
const groupDiv = document.querySelector(`[data-group="${i.id}"]`);
if (groupDiv.querySelectorAll('input:checked').length > 0) preenchidos++;
}
});

// O MoCA possui 12 domínios pontuáveis
const pctGlobal = (preenchidos / 12) * 100;
document.getElementById("progress-bar-global").style.width = `${pctGlobal}%`;
document.getElementById("contadorPreenchidos").textContent = `${preenchidos}/12`;
}

// Dados Toggle
document.getElementById("btnToggleDados").addEventListener("click", function () {
const body = document.getElementById("dadosBody");
const chevron = document.getElementById("dadosChevron");
if (body.classList.contains("open")) {
body.classList.remove("open");
chevron.style.transform = "rotate(0deg)";
this.style.background = "white";
} else {
body.classList.add("open");
chevron.style.transform = "rotate(180deg)";
this.style.background = "#EFF6FF";
}
});
document.getElementById("pacData").value = new Date().toISOString().split("T")[0];

const resultadoSection = document.getElementById("resultado-section");

function calcular() {
let incompleto = false;
let somaTotal = 0;
let dominiosValores = [];
let diagnosticosKeywords = ["cognição", "idoso", "risco"];
let primeiroErro = null;

mocaData.forEach((item) => {
if (item.type === "info") return;

let ptsItem = 0;
let preenchidoItem = false;

if (item.type === "radio") {
const selectVal = document.getElementById(item.id).value;
if (selectVal === "") {
incompleto = true;
document.getElementById(`card_${item.id}`).classList.add("error");
if(!primeiroErro) primeiroErro = document.getElementById(`card_${item.id}`);
} else {
ptsItem = parseInt(selectVal);
preenchidoItem = true;
}
} else if (item.type === "checkbox_group") {
const groupDiv = document.querySelector(`[data-group="${item.id}"]`);
const checked = groupDiv.querySelectorAll('input:checked');
if (checked.length === 0) {
incompleto = true;
document.getElementById(`card_${item.id}`).classList.add("error");
if(!primeiroErro) primeiroErro = document.getElementById(`card_${item.id}`);
} else {
checked.forEach(c => ptsItem += parseInt(c.value));
preenchidoItem = true;
}
}

if (preenchidoItem) {
document.getElementById(`card_${item.id}`).classList.remove("error");
somaTotal += ptsItem;
dominiosValores.push({ nome: item.category.split(":")[0], obtido: ptsItem, max: item.max });

// Alimentando NANDA se o paciente perdeu pontos
if (ptsItem < item.max) {
if (item.id.includes("atencao") || item.id.includes("orientacao")) diagnosticosKeywords.push("confusão");
if (item.id === "evocacao-tardia" || item.id === "nomeacao") diagnosticosKeywords.push("memória", "comunicação");
}
}
});

if (incompleto) {
document.getElementById("msgValidacaoErro").style.display = "block";
if (primeiroErro) primeiroErro.scrollIntoView({ behavior: 'smooth', block: 'center' });
return;
}
document.getElementById("msgValidacaoErro").style.display = "none";

// Bônus Escolaridade
let bonusEscolaridade = 0;
if (document.getElementById("escolaridade-check").checked) {
bonusEscolaridade = 1;
somaTotal += 1;
document.getElementById("linhaEscolaridade").style.display = "table-row";
} else {
document.getElementById("linhaEscolaridade").style.display = "none";
}

if (somaTotal > 30) somaTotal = 30; // Max

// Classificação MoCA
let classe = "", bgPill = "", recomendacao = "";
if (somaTotal >= 26) {
classe = "सामान्य संज्ञान"; bgPill = "#16a34a"; // Verde
recomendacao = "मरीज में वर्तमान स्क्रीनिंग में संज्ञानात्मक गिरावट के महत्वपूर्ण संकेत नहीं हैं।";
} else if (somaTotal >= 18) {
classe = "हल्का संज्ञानात्मक हानि"; bgPill = "#eab308"; // Amarelo
recomendacao = "संभावित हल्के संज्ञानात्मक हानि (एमसीआई) का संकेत देता है। विस्तृत मूल्यांकन और अतिरिक्त न्यूरोसाइकोलॉजिकल परीक्षण की सिफारिश की जाती है।";
} else {
classe = "डिमेंशिया का सुझाव"; bgPill = "#e11d48"; // Vermelho
recomendacao = "गंभीर कमी का संकेत देने वाला कम स्कोर। डिमेंशिया सिंड्रोम के लिए औपचारिक चिकित्सा जांच अनिवार्य है।";
}

document.getElementById("scoreValor").textContent = somaTotal;
const pill = document.getElementById("statusPill");
pill.textContent = classe;
pill.style.backgroundColor = bgPill;

document.getElementById("resultadoMensagem").innerHTML = `प्राप्त स्कोर <strong>30 में से ${somaTotal} अंक</strong> था।<br><br><strong>कार्यवाही:</strong> ${recomendacao}`;

// Tabela Memória
const tbody = document.getElementById("tabelaDominios");
tbody.innerHTML = "";
dominiosValores.forEach((dom) => {
let cor = dom.obtido === dom.max ? "#16a34a" : (dom.obtido === 0 ? "#e11d48" : "#eab308"); 

const tr = document.createElement("tr");
tr.innerHTML = `
<td class="font-bold text-slate-700">${dom.nome}</td>
<td class="text-center font-black" style="color: ${cor}">${dom.obtido}</td>
<td class="text-center text-slate-400">${dom.max}</td>
`;
tbody.appendChild(tr);
});
document.getElementById("totalObtidoTd").textContent = somaTotal;
document.getElementById("totalObtidoTd").style.color = bgPill;

// Parar Cronômetro
clearInterval(timerInterval);
timerInterval = null;

resultadoSection.classList.add("visible");
setTimeout(() => {
resultadoSection.scrollIntoView({ behavior: "smooth", block: "start" });
}, 100);

chamarNanda(diagnosticosKeywords);
}

// NANDA
async function chamarNanda(keywords) {
const lista = document.getElementById("lista-nanda");
lista.innerHTML = '<li class="text-sm text-slate-500 text-center py-4"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512" class="fa-spin mr-2 inline-block" fill="currentColor" width="1em" height="1em"><path d="M304 48a48 48 0 1 0 -96 0 48 48 0 1 0 96 0zm0 416a48 48 0 1 0 -96 0 48 48 0 1 0 96 0zM48 304a48 48 0 1 0 0-96 48 48 0 1 0 0 96zm464-48a48 48 0 1 0 -96 0 48 48 0 1 0 96 0zM142.9 437A48 48 0 1 0 75 369.1 48 48 0 1 0 142.9 437zm0-294.2A48 48 0 1 0 75 75a48 48 0 1 0 67.9 67.9zM369.1 437A48 48 0 1 0 437 369.1 48 48 0 1 0 369.1 437z"/></svg> नैदानिक तर्क प्रक्रिया हो रही है...</li>';

try {
const response = await fetch("/banco_nanda.json");
if (!response.ok) throw new Error("फेच त्रुटि");
const banco = await response.json();

const pontuados = banco
.map((diag) => {
let matchScore = 0;
const texto = (diag.diagnostico + " " + diag.definicao).toLowerCase();
keywords.forEach((kw) => {
if (texto.includes(kw.toLowerCase())) matchScore++;
});
return { ...diag, matchScore };
})
.filter((d) => d.matchScore > 0);

pontuados.sort((a, b) => b.matchScore - a.matchScore);

const uniqueDiagnosticos = [];
const codigosVistos = new Set();
for (const d of pontuados) {
if (!codigosVistos.has(d.codigo)) {
uniqueDiagnosticos.push(d);
codigosVistos.add(d.codigo);
}
if (uniqueDiagnosticos.length >= 6) break;
}

if (uniqueDiagnosticos.length > 0) {
lista.innerHTML = "";
uniqueDiagnosticos.forEach((d) => {
lista.innerHTML += `
<li class="nanda-item flex items-start gap-3">
<span class="bg-blue-100 text-blue-800 text-[10px] font-black px-2 py-1 rounded shadow-sm mt-0.5">${d.codigo}</span>
<div>
<h5 class="text-[13px] font-bold text-slate-800 leading-tight mb-1">${d.diagnostico}</h5>
<p class="text-[11px] text-slate-500 leading-snug m-0">${d.definicao}</p>
</div>
</li>
`;
});
} else {
lista.innerHTML = '<li class="text-xs text-slate-500 text-center py-4">कोई संबंधित निदान नहीं।</li>';
}
} catch (e) {
lista.innerHTML = '<li class="text-xs text-red-500 text-center py-4">NANDA डेटाबेस उपलब्ध नहीं है।</li>';
}
}

