function executarPDF() {
const { jsPDF } = window.jspdf;
const doc = new jsPDF({ orientation: "portrait", unit: "mm", format: "a4" });
const data = getDadosImpressao();

const navy = [26, 62, 116];
const slateLight = [241, 245, 249];
const W = 210, marginL = 18, marginR = 18, usable = W - marginL - marginR;

doc.setFillColor(...navy);
doc.rect(0, 0, W, 32, "F");
doc.setTextColor(255, 255, 255);
doc.setFont("helvetica", "bold");
doc.setFontSize(14);
doc.text("MoCA स्केल", marginL, 13);
doc.setFontSize(9);
doc.setFont("helvetica", "normal");
doc.text("मॉन्ट्रियल संज्ञानात्मक मूल्यांकन", marginL, 20);
