doc.setFont("helvetica", "bold");
doc.setFontSize(9);
doc.text("रोगी की पहचान", marginL + 4, y + 5.5);
y += 12;

if (data.nome) { doc.text("Nome:", marginL, y); doc.setFont("helvetica", "normal"); doc.setTextColor(30, 41, 59); doc.text(data.nome, marginL + 20, y); y += 6; doc.setFont("helvetica", "bold"); doc.setTextColor(...navy); }
if (data.idade) { doc.text("Idade:", marginL, y); doc.setFont("helvetica", "normal"); doc.setTextColor(30, 41, 59); doc.text(data.idade, marginL + 20, y); y += 6; doc.setFont("helvetica", "bold"); doc.setTextColor(...navy); }
if (data.setor) { doc.text("Setor:", marginL, y); doc.setFont("helvetica", "normal"); doc.setTextColor(30, 41, 59); doc.text(data.setor, marginL + 25, y); y += 6; }
y += 4;
}

doc.setFillColor(...navy);
doc.roundedRect(marginL, y, usable, 22, 3, 3, "F");
doc.setTextColor(147, 197, 253);
doc.setFont("helvetica", "bold");
doc.setFontSize(8);
doc.text(`समय: ${data.tempo}`, W / 2, y + 6, { align: "center" });
doc.setTextColor(255, 255, 255);
doc.setFontSize(26);
doc.text(String(data.soma) + " / 30", W / 2, y + 17, { align: "center" });
y += 28;

let pillColor = [22, 163, 74];
if (data.soma < 26) pillColor = [234, 179, 8];
if (data.soma < 18) pillColor = [225, 29, 72];

doc.setFillColor(...pillColor);
doc.roundedRect(marginL, y, usable, 8, 2, 2, "F");
doc.setTextColor(255, 255, 255);
doc.setFont("helvetica", "bold");
doc.setFontSize(9);
doc.text(data.classe.toUpperCase(), W / 2, y + 5.5, { align: "center" });
y += 16;

doc.setFillColor(...slateLight);
doc.roundedRect(marginL, y, usable, 8, 2, 2, "F");
doc.setTextColor(...navy);
doc.text("प्राप्त परिणाम", marginL + 4, y + 5.5);
y += 11;

const rows = [];
const tabelaHtml = document.getElementById("tabelaDominios").querySelectorAll("tr");
tabelaHtml.forEach(tr => {
rows.push([tr.cells[0].innerText, tr.cells[1].innerText, tr.cells[2].innerText]);
});
if(document.getElementById("escolaridade-check").checked) rows.push(["सुधार (≤ 12 वर्षों की शिक्षा)", "+1", "-"]);

doc.autoTable({
startY: y,
margin: { left: marginL, right: marginR, bottom: 20 },
head: [["संज्ञानात्मक क्षेत्र", "Pontos", "Máximo"]],
body: rows,
styles: { fontSize: 8.5, cellPadding: 3, lineColor: [226, 232, 240], lineWidth: 0.3 },
headStyles: { fillColor: navy, textColor: 255, fontStyle: "bold" },
columnStyles: { 0: { cellWidth: 100 }, 1: { halign: "center" }, 2: { halign: "center" } },
alternateRowStyles: { fillColor: [248, 250, 252] },
});

const pageCount = doc.internal.getNumberOfPages();
for(let i = 1; i <= pageCount; i++) {
doc.setPage(i);
let py = 280;
doc.setDrawColor(...slateLight);
doc.setLineWidth(0.3);
doc.line(marginL, py, W - marginR, py);
doc.setTextColor(148, 163, 184);
doc.setFontSize(7.5);
doc.text("NASREDDINE, Z. S. et al. J Am Geriatr Soc (2005).", marginL, py + 5);
doc.text("www.calculadorasdeenfermagem.com.br", W - marginR, py + 5, { align: "right" });
}

const nomeArquivo = data.nome ? `laudo-moca-${data.nome.replace(/\s+/g, "-").toLowerCase()}.pdf` : "laudo-moca.pdf";
doc.save(nomeArquivo);
}

